import { BeforeAfter } from "march/landing"

// pazartesi sabahı: kahveden önce ve sonra; her sürüklemede kaç kez baktığını sayar
const Face = (p: { emoji: string; text: string; tone: string }) =>
  <div sx={{ flex: ["col", "center"], gap: 2, p: 6 }} style={{ minHeight: "14rem", background: p.tone }}>
    <span style={{ fontSize: "4rem" }}>{p.emoji}</span><strong sx={{ text: "lg" }}>{p.text}</strong>
  </div>

export function MondayMorning() {
  let $peeks = 0
  return <div sx={{ flex: "col", gap: 2 }}>
    <BeforeAfter beforeLabel="Kahveden önce" afterLabel="Kahveden sonra" onChange={() => $peeks++}
      before={<Face emoji="😴" text="Beş dakika daha…" tone="#cfd3dc" />}
      after={<Face emoji="🤩" text="Bugün her şeyi yaparım!" tone="#ffd27a" />} />
    <small sx={{ color: "muted" }}>{$peeks} kez kıyasladın</small>
  </div>
}

import { BeforeAfter } from "march/landing"
import { Segmented, Picture } from "march/ui"

// bir fotoğraf düzenleyicinin önizlemesi: aynı fotoğraf, filtresiz ve seçilen filtreyle
const FILTERS = { canlı: "saturate(1.6) contrast(1.1)", sıcak: "sepia(.45) saturate(1.3)", "siyah-beyaz": "grayscale(1) contrast(1.2)" } as const

export function PhotoFilter() {
  let $filter: keyof typeof FILTERS = "canlı"
  return <div sx={{ flex: "col", gap: 3 }}>
    <Segmented aria-label="Filtre" options={Object.keys(FILTERS)} bind:value={$filter} />
    <BeforeAfter ratio="16 / 9" label="Filtre karşılaştırması" beforeLabel="Orijinal" afterLabel={() => $filter}
      before={<Picture src="/media/dusk.jpg" alt="Gün batımı, orijinal" width={1280} height={720} />}
      after={<Picture src="/media/dusk.jpg" alt="Gün batımı, filtreli" width={1280} height={720} style={{ filter: FILTERS[$filter] }} />} />
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { BeforeAfterLab } from "./BeforeAfterLab.tsx"

// BeforeAfterLab'in testleri: kaydedince Testler sekmesinde çalışır
test("tutamaç kendi adı ve değer metniyle bir slider", () => {
  const s = renderTest(() => <BeforeAfterLab />)
  const h = s.get('.lab-ba [role="slider"]')!
  expect(h.getAttribute("aria-label")).toBe("Gece ve gündüz")
  expect(h.getAttribute("aria-valuenow")).toBe("30")
  expect(h.getAttribute("aria-valuetext")).toBe("%30 gece")
})

test("ok tuşu beş adım kaydırır, onChange konumu yazar", async () => {
  const s = renderTest(() => <BeforeAfterLab />)
  await s.press("ArrowRight", s.get('.lab-ba [role="slider"]')!)
  expect(s.get(".lab-pos")?.textContent).toBe("Konum: 35")
  await s.click("Ortala")
  expect(s.get('.lab-ba [role="slider"]')?.getAttribute("aria-valuenow")).toBe("50")
})

test("dikey yön ve yalnız çizgi tutamak", async () => {
  const s = renderTest(() => <BeforeAfterLab />)
  await s.click("dikey")
  expect(s.get(".lab-ba")?.classList.contains("m-ba-vertical")).toBe(true)
  await s.click("çizgi")
  expect(s.container.querySelector(".lab-ba .m-ba-grip")).toBe(null)
})

test("iki köşe etiketi ve iki katman", () => {
  const s = renderTest(() => <BeforeAfterLab />)
  expect(s.all(".lab-ba .m-ba-label").length).toBe(2)
  expect(s.get(".lab-ba .m-ba-before")?.textContent).toContain("Gece")
  expect(s.get(".lab-ba .m-ba-after")?.textContent).toContain("Gündüz")
})
